import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Pedoman Pengamatan Terlebih Dahulu, Kemudian Intervensi Terbatas","description":"","frontmatter":{},"headers":[],"relativePath":"id/83-先观测后有限干涉准则.md","filePath":"id/83-先观测后有限干涉准则.md","lastUpdated":1789183869000}'),r={name:"id/83-先观测后有限干涉准则.md"};function s(u,a,d,m,l,k){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="pedoman-pengamatan-terlebih-dahulu-kemudian-intervensi-terbatas" tabindex="-1">Pedoman Pengamatan Terlebih Dahulu, Kemudian Intervensi Terbatas <a class="header-anchor" href="#pedoman-pengamatan-terlebih-dahulu-kemudian-intervensi-terbatas" aria-label="Permalink to &quot;Pedoman Pengamatan Terlebih Dahulu, Kemudian Intervensi Terbatas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>83</td></tr><tr><td>Modul</td><td>Interaksi Antar Bidang dan Aturan Waktu</td></tr><tr><td>Kata Kunci Inti</td><td>Pengamatan terlebih dahulu, intervensi terbatas, protokol pengamatan, ambang intervensi, evaluasi kausal</td></tr></tbody></table><h2 id="_1-filosofi-inti-pedoman" tabindex="-1">1. Filosofi Inti Pedoman <a class="header-anchor" href="#_1-filosofi-inti-pedoman" aria-label="Permalink to &quot;1. Filosofi Inti Pedoman&quot;">​</a></h2><p>&quot;Pengamatan terlebih dahulu, kemudian intervensi terbatas&quot; adalah pedoman utama untuk operasi mundurnya waktu dan arkeologi antar bidang Hengyuanzhou, filosofi intinya dapat diringkas dalam enam belas karakter: &quot;Amati tanpa menyentuh, ukur tanpa mengganggu, analisis sebelum bertindak, bertindak dengan batasan.&quot; Penetapan pedoman ini didasarkan pada rasa hormat yang mendalam terhadap hukum kausal alam semesta — intervensi langsung apa pun terhadap masa lalu atau bidang lain dapat memicu reaksi berantai kausal yang tidak terduga, dan pengamatan awal yang memadai adalah satu-satunya cara yang dapat diandalkan untuk meminimalkan risiko.</p><p>Dasar filosofis pedoman ini adalah prinsip &quot;kerendahan hati kognitif&quot;. Hengyuanzhou mengakui bahwa bahkan makhluk tertinggi di suatu bidang pun tidak dapat menguasai sepenuhnya semua hubungan kausal dari satu simpul waktu atau satu peradaban bidang. Oleh karena itu, sebelum mengambil tindakan intervensi apa pun, harus dilakukan pengamatan menyeluruh dengan sikap paling hati-hati, memahami struktur kausal dan tren evolusi objek target selengkap mungkin. Hanya di bawah premis data pengamatan yang cukup dan evaluasi risiko yang jelas, intervensi terbatas diizinkan.</p><p>&quot;Pengamatan terlebih dahulu, kemudian intervensi terbatas&quot; bukanlah dua langkah independen, melainkan siklus operasional yang organik: pengamatan memberikan dasar bagi intervensi, dan hasil intervensi memberikan umpan balik sebagai data pengamatan baru, keduanya berputar dan maju secara bertahap. Siklus ini memastikan bahwa setiap intervensi dibangun di atas dasar kognitif terbaru dan terlengkap.</p><h2 id="_2-norma-operasional-tahap-pengamatan" tabindex="-1">2. Norma Operasional Tahap Pengamatan <a class="header-anchor" href="#_2-norma-operasional-tahap-pengamatan" aria-label="Permalink to &quot;2. Norma Operasional Tahap Pengamatan&quot;">​</a></h2><p>Tahap pengamatan adalah dasar dari seluruh proses operasional, kualitasnya secara langsung menentukan keamanan dan efektivitas intervensi selanjutnya. Tahap pengamatan harus mengikuti norma operasional berikut:</p><h3 id="_2-1-persyaratan-durasi-pengamatan" tabindex="-1">2.1 Persyaratan Durasi Pengamatan <a class="header-anchor" href="#_2-1-persyaratan-durasi-pengamatan" aria-label="Permalink to &quot;2.1 Persyaratan Durasi Pengamatan&quot;">​</a></h3><p>Durasi pengamatan tidak boleh kurang dari 1% dari total durasi periode target, dan durasi absolut tidak boleh kurang dari 72 jam waktu standar bidang sendiri. Misalnya, untuk melakukan pengamatan mundur pada periode sejarah dengan durasi 100 tahun, tahap pengamatan murni tidak boleh kurang dari 1 tahun; untuk mengamati periode dengan durasi 10 tahun, tahap pengamatan murni tidak boleh kurang dari 72 jam. Persyaratan durasi minimum ini memastikan bahwa pengamat dapat menangkap perubahan periodik dan tren jangka panjang dalam periode target, menghindari penilaian sepihak karena jendela pengamatan yang terlalu pendek.</p><h3 id="_2-2-persyaratan-dimensi-pengamatan" tabindex="-1">2.2 Persyaratan Dimensi Pengamatan <a class="header-anchor" href="#_2-2-persyaratan-dimensi-pengamatan" aria-label="Permalink to &quot;2.2 Persyaratan Dimensi Pengamatan&quot;">​</a></h3><p>Pengamatan harus mencakup lima dimensi berikut, tidak ada yang boleh kurang:</p><table tabindex="0"><thead><tr><th>Dimensi Pengamatan</th><th>Konten Spesifik</th><th>Metode Pengamatan</th></tr></thead><tbody><tr><td>Dimensi materi</td><td>Lingkungan geografis, ekosistem, infrastruktur, distribusi sumber daya materi</td><td>Pemindaian ruang, analisis materi</td></tr><tr><td>Dimensi energi</td><td>Distribusi kepadatan energi, parameter hukum, pola aliran energi</td><td>Analisis spektrum energi, deteksi hukum</td></tr><tr><td>Dimensi kehidupan</td><td>Distribusi spesies, jumlah populasi, status kesehatan, tingkat evolusi</td><td>Pemindaian tanda kehidupan, pengambilan sampel gen</td></tr><tr><td>Dimensi kesadaran</td><td>Bentuk peradaban, struktur sosial, konsep pemikiran, tren kesadaran kolektif</td><td>Pemantauan pasif domain kesadaran, analisis budaya</td></tr><tr><td>Dimensi kausal</td><td>Rantai kausal kunci, simpul sejarah, tren evolusi, risiko potensial</td><td>Pelacakan rantai kausal, deduksi tren</td></tr></tbody></table><h3 id="_2-3-persyaratan-netralitas-pengamatan" tabindex="-1">2.3 Persyaratan Netralitas Pengamatan <a class="header-anchor" href="#_2-3-persyaratan-netralitas-pengamatan" aria-label="Permalink to &quot;2.3 Persyaratan Netralitas Pengamatan&quot;">​</a></h3><p>Tahap pengamatan harus menjaga netralitas secara ketat, pengamat tidak boleh memengaruhi objek pengamatan dengan cara apa pun. Tindakan terlarang spesifik meliputi: melakukan komunikasi dalam bentuk apa pun dengan objek pengamatan, meninggalkan jejak materi atau energi apa pun di area pengamatan, membimbing atau menyarankan perilaku objek pengamatan, dan melepaskan fluktuasi kehendak apa pun yang dapat dirasakan dalam domain kesadaran.</p><p>Status keberadaan pengamat selama tahap pengamatan harus berupa &quot;persepsi pasif murni&quot;, yaitu hanya menerima informasi tanpa mengeluarkan informasi apa pun. Perangkat penjangkaran neo akan menghasilkan lapangan &quot;perisai pengamatan&quot; untuk pengamat, memastikan bahwa keberadaan pengamat tidak dapat dirasakan oleh objek pengamatan, sekaligus mencegah pengamat melepaskan sinyal gangguan secara tidak sengaja.</p><h2 id="_3-definisi-dan-ambang-batas-intervensi-terbatas" tabindex="-1">3. Definisi dan Ambang Batas Intervensi Terbatas <a class="header-anchor" href="#_3-definisi-dan-ambang-batas-intervensi-terbatas" aria-label="Permalink to &quot;3. Definisi dan Ambang Batas Intervensi Terbatas&quot;">​</a></h2><p>Setelah menyelesaikan tahap pengamatan, tim operasional harus menyerahkan &quot;Laporan Pengamatan dan Evaluasi Kelayakan Intervensi&quot;, dan hanya setelah disetujui oleh Komite Hukum Waktu atau Biro Administrasi Bidang, dapat memasuki tahap intervensi terbatas. &quot;Terbatas&quot; dalam &quot;intervensi terbatas&quot; tercermin dalam tiga tingkat berikut:</p><h3 id="_3-1-cakupan-terbatas" tabindex="-1">3.1 Cakupan Terbatas <a class="header-anchor" href="#_3-1-cakupan-terbatas" aria-label="Permalink to &quot;3.1 Cakupan Terbatas&quot;">​</a></h3><p>Tindakan intervensi harus dibatasi secara ketat dalam &quot;area izin intervensi&quot; yang ditetapkan dalam dokumen persetujuan, area ini biasanya tidak melebihi 1% dari total luas area pengamatan. Tindakan intervensi apa pun di luar area yang diizinkan dianggap sebagai operasi pelanggaran, dan operator akan memikul tanggung jawab hukum.</p><h3 id="_3-2-tingkat-terbatas" tabindex="-1">3.2 Tingkat Terbatas <a class="header-anchor" href="#_3-2-tingkat-terbatas" aria-label="Permalink to &quot;3.2 Tingkat Terbatas&quot;">​</a></h3><p>Output energi dan jumlah injeksi informasi intervensi tidak boleh melebihi &quot;ambang intervensi&quot;. Ambang intervensi ditentukan secara dinamis sesuai dengan sensitivitas kausal objek target, rumus perhitungannya adalah: ambang intervensi = energi total area target × koefisien sensitivitas kausal × 0,0001. Koefisien sensitivitas kausal berkisar antara 0,1 hingga 10; semakin tinggi tingkat peradaban, semakin kritis simpul sejarah, semakin besar koefisiennya. Ini berarti ambang intervensi pada simpul sejarah kritis sangat rendah, hampir tidak mengizinkan injeksi energi substansial apa pun.</p><h3 id="_3-3-waktu-terbatas" tabindex="-1">3.3 Waktu Terbatas <a class="header-anchor" href="#_3-3-waktu-terbatas" aria-label="Permalink to &quot;3.3 Waktu Terbatas&quot;">​</a></h3><p>Durasi tindakan intervensi tidak boleh melebihi 10% dari total durasi tahap pengamatan, dan durasi absolut tidak boleh melebihi 24 jam waktu standar bidang sendiri. Setelah intervensi selesai, operator harus segera mengevakuasi periode target atau bidang target, tidak boleh tinggal.</p><h2 id="_4-evaluasi-dan-koreksi-kausal-setelah-intervensi" tabindex="-1">4. Evaluasi dan Koreksi Kausal Setelah Intervensi <a class="header-anchor" href="#_4-evaluasi-dan-koreksi-kausal-setelah-intervensi" aria-label="Permalink to &quot;4. Evaluasi dan Koreksi Kausal Setelah Intervensi&quot;">​</a></h2><p>Setelah intervensi terbatas selesai, tim operasional harus segera melakukan &quot;evaluasi kausal pasca-intervensi&quot;, memantau perubahan rantai kausal yang disebabkan oleh tindakan intervensi melalui jaringan neo. Isi evaluasi meliputi: besarnya penyimpangan kausal, cakupan penyebaran penyimpangan, tren evolusi jangka panjang penyimpangan, dan apakah ada risiko paradoks.</p><p>Jika evaluasi menemukan bahwa penyimpangan kausal melebihi cakupan yang dapat diterima (besarnya penyimpangan melebihi 0,01% dari total jumlah kausal area target), tim operasional harus segera memulai &quot;prosedur koreksi kausal&quot;. Cara koreksi kausal meliputi: menyuntikkan informasi kompensasi pada simpul waktu berikutnya, melakukan penyesuaian halus rantai kausal melalui jaringan neo, dan dalam kasus ekstrem melakukan mundur kedua untuk menetralkan dampak intervensi sebelumnya.</p><p>Semua tindakan intervensi dan hasil evaluasi kausalnya harus dicatat dalam &quot;Arsip Operasi Waktu&quot;, disimpan secara permanen untuk digunakan dalam audit dan penelitian selanjutnya.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Pedoman pengamatan terlebih dahulu, kemudian intervensi terbatas adalah kristalisasi kebijaksanaan Hengyuanzhou di bidang operasi waktu dan bidang. Dengan pengamatan yang memadai sebagai premis, ambang batas yang ketat sebagai batas, dan evaluasi pasca sebagai jaminan, ia membangun paradigma operasional &quot;mengetahui sebelum bertindak, bertindak dengan batasan&quot;. Tujuan mendasar dari pedoman ini bukanlah mengikat tangan dan kaki eksplorasi, melainkan memastikan bahwa setiap eksplorasi tidak dilakukan dengan mengorbankan penghancuran tatanan kausal alam semesta.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>82-Prinsip Dasar Mundurnya Waktu</li><li>84-Garis Besar Protokol Arkeologi</li><li>89-Mekanisme Pencegahan dan Pengendalian Paradoks Waktu</li></ul>',32)])])}const g=n(r,[["render",s]]);export{o as __pageData,g as default};
